/**
 * LibreCUDA runtime: an implementation of the CUDA runtime API (libcudart) on top of the LibreCUDA driver API.
 *
 * Programs compiled with nvcc call into the runtime in two ways:
 *  - the host code generated by nvcc registers the embedded fat binary, its kernels and its __device__ /
 *    __constant__ variables (__cudaRegisterFatBinary, __cudaRegisterFunction, __cudaRegisterVar) from a static
 *    constructor and launches kernels via __cudaPushCallConfiguration / __cudaPopCallConfiguration /
 *    __cudaGetKernel / __cudaLaunchKernel (the <<<...>>> syntax)
 *  - the program calls the public runtime API (cudaMalloc, cudaMemcpy, ...)
 *
 * The library carries the soname and symbol version of libcudart.so.13, so binaries built with
 * `nvcc -cudart=shared` can run on it unmodified; programs built with `-cudart=none` can link against it directly.
 *
 * Only the public CUDA headers are used (for type definitions); nothing from libcuda/libcudart.
 */
#include <cuda_runtime_api.h>

#include <librecuda.h>

#include <zstd.h>

