// devices

cudaError_t cudaGetDeviceCount(int *count) {
    API_LOCK();
    if (count == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    cudaError_t error = initialize();
    *count = error == cudaSuccess ? static_cast<int>(g_devices.size()) : 0;
    return recordError(error);
}

cudaError_t cudaSetDevice(int device) {
    API_LOCK();
    RT_CHECK(initialize());
    if (device < 0 || device >= static_cast<int>(g_devices.size())) {
        return recordError(cudaErrorInvalidDevice);
    }
    t_device = device;
    return activateDevice(device);
}

cudaError_t cudaInitDevice(int device, unsigned int, unsigned int) {
    API_LOCK();
    return activateDevice(device);
}

cudaError_t cudaGetDevice(int *device) {
    API_LOCK();
    if (device == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(initialize());
    *device = t_device;
    return cudaSuccess;
}

cudaError_t cudaSetDeviceFlags(unsigned int) {
    return cudaSuccess;
}

cudaError_t cudaGetDeviceFlags(unsigned int *flags) {
    if (flags != nullptr) {
        *flags = 0;
    }
    return cudaSuccess;
}

cudaError_t cudaChooseDevice(int *device, const struct cudaDeviceProp *) {
    if (device == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    *device = 0;
    return cudaSuccess;
}

cudaError_t cudaDeviceGetAttribute(int *value, enum cudaDeviceAttr attr, int device) {
    API_LOCK();
    if (value == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    int previous = t_device;
    RT_CHECK(activateDevice(device));
    // the runtime attribute numbering is the same as the driver's
    if (libreCuDeviceGetAttribute(value, static_cast<LibreCuDeviceAttribute>(attr), g_devices[device].device) != 0) {
        // attribute not known to LibreCUDA: report the feature as unsupported
        *value = 0;
    }
    activateDevice(previous);
    return cudaSuccess;
}

static int deviceAttribute(int device, LibreCuDeviceAttribute attr) {
    int value = 0;
    libreCuDeviceGetAttribute(&value, attr, g_devices[device].device);
    return value;
}

cudaError_t cudaGetDeviceProperties(struct cudaDeviceProp *prop, int device) {
    API_LOCK();
    if (prop == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    int previous = t_device;
    RT_CHECK(activateDevice(device));
    LibreCUdevice dev = g_devices[device].device;
    memset(prop, 0, sizeof(*prop));
    libreCuDeviceGetName(prop->name, sizeof(prop->name), dev);
    libreCuDeviceGetUuid(reinterpret_cast<uint8_t *>(prop->uuid.bytes), dev);
    size_t total_mem{};
    libreCuDeviceTotalMem(&total_mem, dev);
    prop->totalGlobalMem = total_mem;
    prop->sharedMemPerBlock = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK);
    prop->regsPerBlock = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_REGISTERS_PER_BLOCK);
    prop->warpSize = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_WARP_SIZE);
    prop->memPitch = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_PITCH);
    prop->maxThreadsPerBlock = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_THREADS_PER_BLOCK);
    prop->maxThreadsDim[0] = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_BLOCK_DIM_X);
    prop->maxThreadsDim[1] = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_BLOCK_DIM_Y);
    prop->maxThreadsDim[2] = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_BLOCK_DIM_Z);
    prop->maxGridSize[0] = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_GRID_DIM_X);
    prop->maxGridSize[1] = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_GRID_DIM_Y);
    prop->maxGridSize[2] = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_GRID_DIM_Z);
    prop->totalConstMem = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_TOTAL_CONSTANT_MEMORY);
    prop->major = g_devices[device].ccMajor;
    prop->minor = g_devices[device].ccMinor;
    prop->textureAlignment = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_TEXTURE_ALIGNMENT);
    prop->texturePitchAlignment = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_TEXTURE_PITCH_ALIGNMENT);
    prop->multiProcessorCount = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT);
    prop->integrated = 0;
    prop->canMapHostMemory = 1;
    prop->surfaceAlignment = 512;
    prop->concurrentKernels = 1;
    prop->cooperativeLaunch = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_COOPERATIVE_LAUNCH);
    prop->pciBusID = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_PCI_BUS_ID);
    prop->pciDeviceID = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_PCI_DEVICE_ID);
    prop->pciDomainID = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_PCI_DOMAIN_ID);
    prop->asyncEngineCount = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_ASYNC_ENGINE_COUNT);
    prop->unifiedAddressing = 1;
    prop->memoryBusWidth = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_GLOBAL_MEMORY_BUS_WIDTH);
    prop->l2CacheSize = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_L2_CACHE_SIZE);
    prop->maxThreadsPerMultiProcessor = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_THREADS_PER_MULTIPROCESSOR);
    prop->globalL1CacheSupported = 1;
    prop->localL1CacheSupported = 1;
    prop->sharedMemPerMultiprocessor = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_MULTIPROCESSOR);
    prop->regsPerMultiprocessor = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_REGISTERS_PER_MULTIPROCESSOR);
    prop->computePreemptionSupported = 1;
    prop->sharedMemPerBlockOptin = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN);
    prop->maxBlocksPerMultiProcessor = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_MAX_BLOCKS_PER_MULTIPROCESSOR);
    prop->reservedSharedMemPerBlock = deviceAttribute(device, CU_DEVICE_ATTRIBUTE_RESERVED_SHARED_MEMORY_PER_BLOCK);
    prop->deviceNumaId = -1;
    prop->hostNumaId = -1;
    activateDevice(previous);
    return cudaSuccess;
}

cudaError_t cudaDeviceGetPCIBusId(char *pciBusId, int len, int device) {
    API_LOCK();
    RT_CHECK(activateDevice(device));
    snprintf(pciBusId, len, "%08X:%02X:%02X.0", deviceAttribute(device, CU_DEVICE_ATTRIBUTE_PCI_DOMAIN_ID),
             deviceAttribute(device, CU_DEVICE_ATTRIBUTE_PCI_BUS_ID),
             deviceAttribute(device, CU_DEVICE_ATTRIBUTE_PCI_DEVICE_ID));
    activateCurrentDevice();
    return cudaSuccess;
}

cudaError_t cudaDeviceSynchronize(void) {
    API_LOCK();
    RT_CHECK(prohibitedDuringCapture());
    RT_CHECK(activateCurrentDevice());
    return synchronizeDevice(t_device);
}

cudaError_t cudaDeviceReset(void) {
    API_LOCK();
    if (!g_initialized || g_initError != cudaSuccess) {
        return cudaSuccess;
    }
    return resetDevice(t_device);
}

cudaError_t cudaThreadSynchronize(void) {
    return cudaDeviceSynchronize();
}

cudaError_t cudaDeviceSetLimit(enum cudaLimit limit, size_t value) {
    API_LOCK();
    RT_CHECK(activateCurrentDevice());
    if (limit == cudaLimitStackSize) {
        LC_CHECK(libreCuCtxSetStackLimit(value));
    } else if (limit == cudaLimitPrintfFifoSize) {
        LC_CHECK(libreCuCtxSetPrintfFifoSize(value));
    } else if (limit == cudaLimitMallocHeapSize) {
        LC_CHECK(libreCuCtxSetMallocHeapSize(value));
    } else if (limit == cudaLimitDevRuntimePendingLaunchCount) {
        if (value > UINT32_MAX) {
            return recordError(cudaErrorInvalidValue);
        }
        LC_CHECK(libreCuCtxSetDeviceLaunchQueueSize(static_cast<uint32_t>(value)));
    }
    return cudaSuccess;
}

cudaError_t cudaDeviceGetLimit(size_t *pValue, enum cudaLimit limit) {
    API_LOCK();
    if (pValue == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    switch (limit) {
        case cudaLimitStackSize:
            LC_CHECK(libreCuCtxGetStackLimit(pValue));
            break;
        case cudaLimitPrintfFifoSize:
            LC_CHECK(libreCuCtxGetPrintfFifoSize(pValue));
            break;
        case cudaLimitMallocHeapSize:
            LC_CHECK(libreCuCtxGetMallocHeapSize(pValue));
            break;
        case cudaLimitDevRuntimePendingLaunchCount: {
            uint32_t launches{};
            LC_CHECK(libreCuCtxGetDeviceLaunchQueueSize(&launches));
            *pValue = launches;
            break;
        }
        case cudaLimitDevRuntimeSyncDepth:
            // device side synchronization doesn't exist since CUDA 12; the nesting depth of launches is 24
            *pValue = 2;
            break;
        default:
            *pValue = 0;
            break;
    }
    return cudaSuccess;
}

cudaError_t cudaDeviceSetCacheConfig(enum cudaFuncCache) {
    return cudaSuccess;
}

cudaError_t cudaDeviceGetCacheConfig(enum cudaFuncCache *pCacheConfig) {
    if (pCacheConfig != nullptr) {
        *pCacheConfig = cudaFuncCachePreferNone;
    }
    return cudaSuccess;
}

cudaError_t cudaDeviceGetStreamPriorityRange(int *leastPriority, int *greatestPriority) {
    if (leastPriority != nullptr) {
        *leastPriority = 0;
    }
    if (greatestPriority != nullptr) {
        *greatestPriority = 0;
    }
    return cudaSuccess;
}

static cudaError_t p2pCapabilities(int device, int peer, bool *pRead, bool *pWrite, bool *pAtomics) {
    RT_CHECK(initialize());
    if (device < 0 || device >= static_cast<int>(g_devices.size()) || peer < 0 ||
        peer >= static_cast<int>(g_devices.size())) {
        return recordError(cudaErrorInvalidDevice);
    }
    LC_CHECK(libreCuDeviceGetP2PCapabilities(g_devices[device].device, g_devices[peer].device, pRead, pWrite,
                                             pAtomics));
    return cudaSuccess;
}

cudaError_t cudaDeviceCanAccessPeer(int *canAccessPeer, int device, int peerDevice) {
    API_LOCK();
    if (canAccessPeer == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    bool read{}, write{}, atomics{};
    RT_CHECK(p2pCapabilities(device, peerDevice, &read, &write, &atomics));
    *canAccessPeer = device != peerDevice && read && write;
    return cudaSuccess;
}

cudaError_t cudaDeviceGetP2PAttribute(int *value, enum cudaDeviceP2PAttr attr, int srcDevice, int dstDevice) {
    API_LOCK();
    if (value == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    bool read{}, write{}, atomics{};
    RT_CHECK(p2pCapabilities(srcDevice, dstDevice, &read, &write, &atomics));
    if (srcDevice == dstDevice) {
        return recordError(cudaErrorInvalidDevice);
    }
    switch (attr) {
        case cudaDevP2PAttrPerformanceRank:
        case cudaDevP2PAttrOnlyPartialNativeAtomicSupported:
            *value = 0;
            break;
        case cudaDevP2PAttrAccessSupported:
        case cudaDevP2PAttrCudaArrayAccessSupported:
            *value = read && write;
            break;
        case cudaDevP2PAttrNativeAtomicSupported:
            *value = read && write && atomics;
            break;
        default:
            return recordError(cudaErrorInvalidValue);
    }
    return cudaSuccess;
}

/**
 * Gives the current device's GPU access to the memory of peerDevice: the peer's allocations (existing and future)
 * are mapped on it at the same addresses
 */
cudaError_t cudaDeviceEnablePeerAccess(int peerDevice, unsigned int flags) {
    API_LOCK();
    RT_CHECK(initialize());
    if (peerDevice < 0 || peerDevice >= static_cast<int>(g_devices.size())) {
        return recordError(cudaErrorInvalidDevice);
    }
    if (peerDevice == t_device) {
        return recordError(cudaErrorPeerAccessUnsupported);
    }
    if (flags != 0) {
        return recordError(cudaErrorInvalidValue);
    }
    const int device = t_device;
    RT_CHECK(activateDevice(peerDevice));
    RT_CHECK(activateDevice(device));
    LC_CHECK(libreCuCtxEnablePeerAccess(g_devices[peerDevice].ctx, 0));
    return cudaSuccess;
}

cudaError_t cudaDeviceDisablePeerAccess(int peerDevice) {
    API_LOCK();
    RT_CHECK(initialize());
    if (peerDevice < 0 || peerDevice >= static_cast<int>(g_devices.size()) || peerDevice == t_device) {
        return recordError(cudaErrorInvalidDevice);
    }
    RT_CHECK(activateCurrentDevice());
    if (g_devices[peerDevice].ctx == nullptr) {
        return recordError(cudaErrorPeerAccessNotEnabled);
    }
    LC_CHECK(libreCuCtxDisablePeerAccess(g_devices[peerDevice].ctx));
    return cudaSuccess;
}

// ---------------------------------------------------------------------------------------------------------------------
// memory

cudaError_t cudaMalloc(void **devPtr, size_t size) {
    API_SHARED_LOCK();
    // potentially unsafe during stream capture (CUDA: allocations / implicit synchronization)
    RT_CHECK(prohibitedDuringCapture());
    if (devPtr == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    if (size == 0) {
        *devPtr = nullptr;
        return cudaSuccess;
    }
    LC_CHECK(libreCuMemAlloc(devPtr, size, false));
    return cudaSuccess;
}

cudaError_t cudaFree(void *devPtr) {
    API_LOCK();
    // potentially unsafe during stream capture (CUDA: allocations / implicit synchronization)
    RT_CHECK(prohibitedDuringCapture());
    RT_CHECK(activateCurrentDevice());
    if (devPtr == nullptr) {
        return cudaSuccess;
    }
    // memory may still be in use by queued work (of its device or, with peer access, the current one)
    RT_CHECK(synchronizeDevice(t_device));
    const int owner = ownerDevice(devPtr);
    if (owner >= 0 && owner != t_device) {
        RT_CHECK(synchronizeDevice(owner));
    }
    LC_CHECK(libreCuMemFree(devPtr));
    return cudaSuccess;
}

cudaError_t cudaMallocAsync(void **devPtr, size_t size, cudaStream_t) {
    return cudaMalloc(devPtr, size);
}

cudaError_t cudaFreeAsync(void *devPtr, cudaStream_t) {
    return cudaFree(devPtr);
}

cudaError_t cudaMallocPitch(void **devPtr, size_t *pitch, size_t width, size_t height) {
    if (pitch == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    *pitch = (width + 511) & ~size_t(511);
    return cudaMalloc(devPtr, *pitch * height);
}

cudaError_t cudaMallocManaged(void **devPtr, size_t size, unsigned int) {
    API_LOCK();
    if (devPtr == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    // device memory that is also mapped into the CPU address space (through BAR1) at the same address
    LC_CHECK(libreCuMemAlloc(devPtr, size, true));
    return cudaSuccess;
}

cudaError_t cudaMallocHost(void **ptr, size_t size) {
    API_LOCK();
    // potentially unsafe during stream capture (CUDA: allocations / implicit synchronization)
    RT_CHECK(prohibitedDuringCapture());
    if (ptr == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    if (size == 0) {
        *ptr = nullptr;
        return cudaSuccess;
    }
    LC_CHECK(libreCuMemAllocHost(ptr, size));
    return cudaSuccess;
}

cudaError_t cudaHostAlloc(void **pHost, size_t size, unsigned int) {
    return cudaMallocHost(pHost, size);
}

cudaError_t cudaFreeHost(void *ptr) {
    API_LOCK();
    // potentially unsafe during stream capture (CUDA: allocations / implicit synchronization)
    RT_CHECK(prohibitedDuringCapture());
    if (ptr == nullptr) {
        return cudaSuccess;
    }
    RT_CHECK(activateCurrentDevice());
    // page-locked memory is usable from every device
    for (size_t device = 0; device < g_devices.size(); device++) {
        RT_CHECK(synchronizeDevice(static_cast<int>(device)));
    }
    LC_CHECK(libreCuMemFreeHost(ptr));
    return cudaSuccess;
}

cudaError_t cudaHostGetDevicePointer(void **pDevice, void *pHost, unsigned int) {
    API_LOCK();
    if (pDevice == nullptr || !libreCuMemIsPinnedHost(pHost)) {
        return recordError(cudaErrorInvalidValue);
    }
    // pinned host memory is mapped at the same address on the GPU
    *pDevice = pHost;
    return cudaSuccess;
}

cudaError_t cudaHostGetFlags(unsigned int *pFlags, void *pHost) {
    if (pFlags == nullptr || !libreCuMemIsPinnedHost(pHost)) {
        return recordError(cudaErrorInvalidValue);
    }
    *pFlags = cudaHostAllocMapped;
    return cudaSuccess;
}

cudaError_t cudaHostRegister(void *, size_t, unsigned int) {
    // registration is not needed for correctness: copies from unregistered memory are staged
    return cudaSuccess;
}

cudaError_t cudaHostUnregister(void *) {
    return cudaSuccess;
}

cudaError_t cudaMemGetInfo(size_t *free, size_t *total) {
    API_LOCK();
    RT_CHECK(activateCurrentDevice());
    LC_CHECK(libreCuMemGetInfo(free, total));
    return cudaSuccess;
}

cudaError_t cudaPointerGetAttributes(struct cudaPointerAttributes *attributes, const void *ptr) {
    API_LOCK();
    if (attributes == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    memset(attributes, 0, sizeof(*attributes));
    attributes->device = std::max(ownerDevice(ptr), 0);
    switch (classify(ptr)) {
        case PtrKind::DEVICE:
            attributes->type = cudaMemoryTypeDevice;
            attributes->devicePointer = const_cast<void *>(ptr);
            break;
        case PtrKind::PINNED:
            attributes->type = cudaMemoryTypeHost;
            attributes->devicePointer = const_cast<void *>(ptr);
            attributes->hostPointer = const_cast<void *>(ptr);
            break;
        case PtrKind::PAGEABLE:
            attributes->type = cudaMemoryTypeUnregistered;
            attributes->device = -2;
            attributes->hostPointer = const_cast<void *>(ptr);
            break;
    }
    return cudaSuccess;
}

cudaError_t cudaMemcpy(void *dst, const void *src, size_t count, enum cudaMemcpyKind) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(nullptr, &stream));
    return memcpyOnStream(dst, src, count, stream, true);
}

cudaError_t cudaMemcpyAsync(void *dst, const void *src, size_t count, enum cudaMemcpyKind, cudaStream_t handle) {
    STREAM_OP_LOCK(handle);
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    return memcpyOnStream(dst, src, count, stream, false);
}

static bool validDevice(int device) {
    return device >= 0 && device < static_cast<int>(g_devices.size());
}

// the devices of the pointers follow from their addresses (unified addressing)
cudaError_t cudaMemcpyPeer(void *dst, int dstDevice, const void *src, int srcDevice, size_t count) {
    API_LOCK();
    RT_CHECK(initialize());
    if (!validDevice(dstDevice) || !validDevice(srcDevice)) {
        return recordError(cudaErrorInvalidDevice);
    }
    return cudaMemcpy(dst, src, count, cudaMemcpyDefault);
}

cudaError_t cudaMemcpyPeerAsync(void *dst, int dstDevice, const void *src, int srcDevice, size_t count,
                                cudaStream_t stream) {
    {
        API_LOCK();
        RT_CHECK(initialize());
        if (!validDevice(dstDevice) || !validDevice(srcDevice)) {
            return recordError(cudaErrorInvalidDevice);
        }
    }
    return cudaMemcpyAsync(dst, src, count, cudaMemcpyDefault, stream);
}

static cudaError_t memcpy2D(void *dst, size_t dpitch, const void *src, size_t spitch, size_t width, size_t height,
                            cudaStream_t handle, bool synchronous) {
    API_LOCK();
    if (width > dpitch || width > spitch) {
        return recordError(cudaErrorInvalidPitchValue);
    }
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    if (capturing(stream)) {
        if (synchronous || classify(dst) == PtrKind::PAGEABLE || classify(src) == PtrKind::PAGEABLE) {
            return captureUnsupported(stream);
        }
        cudaMemcpy3DParms p{};
        p.dstPtr = cudaPitchedPtr{dst, dpitch, width, height};
        p.srcPtr = cudaPitchedPtr{const_cast<void *>(src), spitch, width, height};
        p.extent = cudaExtent{width, height, 1};
        p.kind = cudaMemcpyDefault;
        return captureCopy(stream, p);
    }
    if (dpitch == width && spitch == width) {
        return memcpyOnStream(dst, src, width * height, stream, synchronous);
    }
    for (size_t row = 0; row < height; row++) {
        RT_CHECK(memcpyOnStream(static_cast<uint8_t *>(dst) + row * dpitch,
                                static_cast<const uint8_t *>(src) + row * spitch, width, stream, false));
    }
    if (synchronous) {
        RT_CHECK(synchronizeStream(stream));
    }
    return cudaSuccess;
}

cudaError_t cudaMemcpy2D(void *dst, size_t dpitch, const void *src, size_t spitch, size_t width, size_t height,
                         enum cudaMemcpyKind) {
    return memcpy2D(dst, dpitch, src, spitch, width, height, nullptr, true);
}

cudaError_t cudaMemcpy2DAsync(void *dst, size_t dpitch, const void *src, size_t spitch, size_t width, size_t height,
                              enum cudaMemcpyKind, cudaStream_t stream) {
    return memcpy2D(dst, dpitch, src, spitch, width, height, stream, false);
}

cudaError_t cudaMemset(void *devPtr, int value, size_t count) {
    API_LOCK();
    CUstream_st *stream{};
    RT_CHECK(resolveStream(nullptr, &stream));
    // like CUDA, memset on device memory is asynchronous with respect to the host
    return memsetOnStream(devPtr, value, count, stream, false);
}

cudaError_t cudaMemsetAsync(void *devPtr, int value, size_t count, cudaStream_t handle) {
    STREAM_OP_LOCK(handle);
    CUstream_st *stream{};
    RT_CHECK(resolveStream(handle, &stream));
    return memsetOnStream(devPtr, value, count, stream, false);
}

